## 🎯 Dans cette leçon

L'**Arduino Uno** est la carte de référence de ce livre : solide, bon marché, en logique 5 V, avec des milliers d'exemples en ligne. On écrit un programme sur l'ordinateur, on l'envoie par USB, et la carte l'exécute toute seule.

À la fin de cette leçon, tu sauras :

- repérer les broches numériques, PWM, analogiques et d'alimentation ;
- connaître les limites électriques de la carte (5 V, 20 mA par broche) ;
- expliquer le rôle de `setup()` et `loop()` ;
- téléverser un programme et lire le **moniteur série** ;
- calculer la résistance d'une LED branchée sur une sortie.

blocs.code:
// Leçon 4.1 — Blink : clignoter et écrire sur le PC
const int LED = 13;   // LED externe + LED « L » de la carte
int compteur = 0;

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);                      // même vitesse que le moniteur
  Serial.println("Bonjour, ici l'Arduino Uno !");
}

void loop() {
  digitalWrite(LED, HIGH);  delay(500);    // allumée 0,5 s
  digitalWrite(LED, LOW);   delay(500);    // éteinte 0,5 s
  compteur++;
  Serial.print("Clignotements : ");
  Serial.println(compteur);
}

// Solution du mini-défi : SOS en morse sur D13
const int LED = 13;
const int POINT = 200;   // éclat court (ms)
const int TRAIT = 600;   // éclat long = 3 points

void eclat(int duree) {
  digitalWrite(LED, HIGH); delay(duree);
  digitalWrite(LED, LOW);  delay(POINT);      // pause entre deux éclats
}

void lettre(int duree) {
  for (int i = 0; i < 3; i++) eclat(duree);   // S = 3 points, O = 3 traits
  delay(2 * POINT);                           // pause entre deux lettres
}

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  lettre(POINT); lettre(TRAIT); lettre(POINT);   // S O S
  Serial.println("SOS");
  delay(1400);                                    // pause entre deux messages
}

