## 🎯 Dans cette leçon

L'**ESP8266** réunit dans une seule puce un processeur 32 bits et une **radio Wi-Fi**. Monté sur une carte **NodeMCU**, il se programme comme un Arduino et envoie ses mesures sur Internet pour quelques euros.

À la fin de cette leçon, tu sauras :

- installer le paquet de cartes « esp8266 » dans l'IDE ;
- traduire les noms D0 à D8 en numéros GPIO ;
- respecter la logique 3,3 V ;
- te connecter à un réseau Wi-Fi et lire l'adresse IP ;
- calculer l'autonomie d'un capteur sur pile avec le sommeil profond.

blocs.code:
// Leçon 4.3 — connexion Wi-Fi et adresse IP (carte NodeMCU 1.0)
#include <ESP8266WiFi.h>   // fournie avec le paquet « esp8266 »
const int LED = D1;        // LED externe sur GPIO5

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  WiFi.mode(WIFI_STA);                    // simple client du réseau
  WiFi.begin("MonWiFi", "motdepasse");   // nom du réseau, clé
  Serial.print("Connexion");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  digitalWrite(LED, HIGH);                 // connecté : LED allumée
  Serial.print("\nAdresse IP : ");
  Serial.println(WiFi.localIP());
}

void loop() {
  Serial.print("Signal : ");
  Serial.print(WiFi.RSSI());               // en dBm
  Serial.println(" dBm");
  delay(2000);
}

// Solution du mini-défi : LED clignotante pendant la connexion
#include <ESP8266WiFi.h>
const int LED = D1;

void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  WiFi.begin("MonWiFi", "motdepasse");
  while (WiFi.status() != WL_CONNECTED) {
    digitalWrite(LED, !digitalRead(LED));   // clignote
    delay(250);
  }
  digitalWrite(LED, HIGH);                  // fixe : connecté
  Serial.println(WiFi.localIP());
  Serial.print("Signal : "); Serial.print(WiFi.RSSI()); Serial.println(" dBm");
}

void loop() { }

