## 🎯 Dans cette leçon

L'**ESP32** réunit deux cœurs de calcul, le **Wi-Fi** et le **Bluetooth** dans une seule puce. C'est la carte des objets connectés complets : capteurs, serveur web, envoi de données vers Internet, sans module supplémentaire. C'est aussi la carte des projets FOUNATEK NEXUS.

À la fin de cette leçon, tu sauras :

- installer et programmer une DevKit dans l'Arduino IDE ;
- choisir les bonnes broches (ADC1, ADC2, démarrage, flash) ;
- convertir une lecture 12 bits en tension, et créer une tension avec le DAC ;
- créer un mini **serveur web** qui commande une LED depuis un téléphone.

blocs.code:
// Leçon 4.4 — un mini serveur web qui commande une LED (ESP32 Dev Module)
#include <WiFi.h>
#include <WebServer.h>      // fournie avec le paquet « esp32 »

const int LED = 23;
WebServer serveur(80);      // serveur web sur le port 80

void allumer()  { digitalWrite(LED, HIGH); serveur.send(200, "text/plain", "LED ON"); }
void eteindre() { digitalWrite(LED, LOW);  serveur.send(200, "text/plain", "LED OFF"); }

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(115200);
  WiFi.begin("MonWiFi", "motdepasse");
  while (WiFi.status() != WL_CONNECTED) delay(500);
  Serial.print("Ouvre http://");
  Serial.println(WiFi.localIP());          // adresse à taper sur le téléphone
  serveur.on("/on", allumer);
  serveur.on("/off", eteindre);
  serveur.begin();
}

void loop() {
  serveur.handleClient();                  // traite les requêtes reçues
}

// Solution du mini-défi : page d'accueil avec liens et mesure du potentiomètre
#include <WiFi.h>
#include <WebServer.h>

const int LED = 23, POT = 34;   // GPIO 34 : ADC1, fonctionne avec le Wi-Fi
WebServer serveur(80);

void accueil() {
  float u = analogRead(POT) * 3.3 / 4095;
  String page = "<h1>ESP32 FOUNATEK</h1>";
  page += "<p>Potentiometre : " + String(u, 2) + " V</p>";
  page += "<p><a href='/on'>ON</a> | <a href='/off'>OFF</a></p>";
  serveur.send(200, "text/html", page);
}
void allumer()  { digitalWrite(LED, HIGH); accueil(); }
void eteindre() { digitalWrite(LED, LOW);  accueil(); }

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(115200);
  WiFi.begin("MonWiFi", "motdepasse");
  while (WiFi.status() != WL_CONNECTED) delay(500);
  Serial.println(WiFi.localIP());
  serveur.on("/", accueil);
  serveur.on("/on", allumer);
  serveur.on("/off", eteindre);
  serveur.begin();
}

void loop() { serveur.handleClient(); }

