// Leçon 4.5 — l'exemple CameraWebServer, à adapter en 3 lignes
// Fichier > Exemples > ESP32 > Camera > CameraWebServer

// 1) Dans l'onglet principal, un seul modèle actif :
#define CAMERA_MODEL_AI_THINKER      // carte AI-Thinker

// 2) Ton réseau Wi-Fi (2,4 GHz) :
const char *ssid = "MonWiFi";
const char *password = "motdepasse";

// 3) Outils > Carte : « AI Thinker ESP32-CAM »
//    Outils > Partition Scheme : « Huge APP » si le programme est trop gros
// 4) IO0 relié à GND, RESET, puis Téléverser
// 5) Retirer le fil IO0 - GND, appuyer sur RESET
// 6) Moniteur série à 115200 bauds :
//      Camera Ready! Use 'http://192.168.1.42' to connect
// 7) Ouvrir cette adresse dans le navigateur, puis « Start Stream »

// Solution du mini-défi : une photo JPEG sur la microSD à chaque mouvement
#include "esp_camera.h"
#include "FS.h"
#include "SD_MMC.h"

const int PIR = 13;      // sortie du HC-SR501 (alimenté en 5 V, sortie en 3,3 V)
int numero = 0;

void setup() {
  Serial.begin(115200);
  pinMode(PIR, INPUT);
  camera_config_t c = {};                  // brochage de la carte AI-Thinker
  c.ledc_channel = LEDC_CHANNEL_0;  c.ledc_timer = LEDC_TIMER_0;
  c.pin_d0 = 5;   c.pin_d1 = 18;  c.pin_d2 = 19;  c.pin_d3 = 21;
  c.pin_d4 = 36;  c.pin_d5 = 39;  c.pin_d6 = 34;  c.pin_d7 = 35;
  c.pin_xclk = 0;  c.pin_pclk = 22;  c.pin_vsync = 25;  c.pin_href = 23;
  c.pin_sccb_sda = 26;  c.pin_sccb_scl = 27;  c.pin_pwdn = 32;  c.pin_reset = -1;
  c.xclk_freq_hz = 20000000;
  c.pixel_format = PIXFORMAT_JPEG;
  c.frame_size = FRAMESIZE_VGA;            // 640 x 480
  c.jpeg_quality = 12;                     // 0 = meilleure qualité, 63 = la plus faible
  c.fb_count = 1;
  if (esp_camera_init(&c) != ESP_OK) { Serial.println("Camera init failed"); return; }
  if (!SD_MMC.begin("/sdcard", true)) {   // true = mode 1 bit
    Serial.println("Carte microSD absente"); return;
  }
  Serial.println("Pret : en attente d'un mouvement");
}

void loop() {
  if (digitalRead(PIR) == HIGH) {
    camera_fb_t *img = esp_camera_fb_get();          // prend la photo
    if (img) {
      String nom = "/photo" + String(numero++) + ".jpg";
      File f = SD_MMC.open(nom, FILE_WRITE);
      f.write(img->buf, img->len);
      f.close();
      Serial.printf("%s : %u octets\n", nom.c_str(), img->len);
      esp_camera_fb_return(img);                     // libère la mémoire
    }
    delay(5000);                                     // une photo au plus toutes les 5 s
  }
}

